<script setup lang="ts">
import SignupFields from './SignupFields.vue';
import ActivityMaterialsSettings from './ActivityMaterialsSettings.vue';
import SignupSuccess from './SignupSuccess.vue';
import MaterialsGallery from './MaterialsGallery.vue';
import {safeMaterialLink,type ActivityMaterials} from './materials';
const materialsSettings=ref<InstanceType<typeof ActivityMaterialsSettings>|null>(null),materialsUploading=ref(false);
const materialsPreview=ref<ActivityMaterials|null>(null),previewMaterialsOpen=ref(false);
function openMaterialsPreview(){if(materialsPreview.value?.type==='images')previewMaterialsOpen.value=true;else if(materialsPreview.value?.type==='link'){const url=safeMaterialLink(materialsPreview.value.link);if(url)window.open(url,'_blank','noopener,noreferrer');}}

import {showNotice} from './notices';
const previewFields=ref<InstanceType<typeof SignupFields>|null>(null);
function previewSignup(){const issue=previewFields.value?.validate();if(!issue)showNotice('这是实时外观预览，不会提交签到','info');}
import {ElTabs,ElTabPane,ElAlert} from 'element-plus';
import 'element-plus/es/components/alert/style/css';
import 'element-plus/es/components/tabs/style/css';
import {ElInputNumber,ElCard} from 'element-plus';
import 'element-plus/es/components/input-number/style/css';
import 'element-plus/es/components/card/style/css';
import {ElForm} from 'element-plus';
import 'element-plus/es/components/form/style/css';
import {ElButton,ElInput,ElSelect,ElOption,ElCheckbox,ElDialog} from 'element-plus';
import 'element-plus/es/components/button/style/css';
import 'element-plus/es/components/input/style/css';
import 'element-plus/es/components/select/style/css';
import 'element-plus/es/components/checkbox/style/css';
import 'element-plus/es/components/dialog/style/css';
import TopNotice from './TopNotice.vue';
import {ref,computed,watch,reactive,nextTick} from 'vue';
import {get,write,RequestError} from './api';
type Field={id:string;name:string;type:'text'|'number'|'single'|'multiple';hint:string;required:boolean;options:{id:string;label:string}[]};
type Prize={id:string;name:string;total:number;batch:number;mode:string;theme:string};
type Config={materials:ActivityMaterials;lockedPrizeIds:string[];version:string;phase:string;firstFormalStarted:boolean;wechatVerified:boolean;form:{fields:Field[];titleFieldId:string|null;auxiliaryFieldIds:string[];signupFieldIds:string[]};rule:{mode:string;maxWins:number|null};prizes:Prize[];participants:{id:string;nickname:string;eligible:boolean}[];reservations:{prize_id:string;participant_id:string}[];runs:{mode:string;generation:number;participants:number;simulated:number;rounds:number;awards:number;drawing:boolean}[]};
type Person={id:string;nickname:string;eligible:boolean};
const queries=reactive<Record<string,string>>({}),results=reactive<Record<string,Person[]>>({}),searching=reactive<Record<string,boolean>>({}),totals=reactive<Record<string,number>>({});
const checkinTab=ref('background'),prizeTab=ref('prizes'),modeTab=ref('cleanup');
function revealInvalidField(event:Event){const targetTab=props.section==='form'?checkinTab:prizeTab;const target=props.section==='form'?'fields':(event.target as HTMLElement).closest('.rule-panel')?'rules':'prizes';if(targetTab.value===target)return;event.preventDefault();targetTab.value=target;const input=event.target as HTMLInputElement;void nextTick(()=>{input.focus();input.reportValidity();});}
const uuid=()=>crypto.randomUUID();
const props=defineProps<{activityId:string;revision:string;activityName?:string;logoUrl?:string;backgroundUrl?:string;backgroundId?:string|null;showBackground?:boolean;uploading?:boolean;organizer?:string;section:'form'|'prizes'|'mode'}>();
const emit=defineEmits<{changed:[];expired:[]}>();
const data=ref<Config|null>(null),error=ref(''),message=ref(''),saving=ref(false),confirmation=ref(''),reason=ref(''),preview=ref(false),answers=ref<Record<string,string|string[]>>({}),dirty=ref(false);
const locked=computed(()=>props.uploading||materialsUploading.value||!data.value||data.value.phase==='expired'||saving.value||data.value.runs.some(r=>r.drawing));
const simulationCount=ref<number|undefined>(2000);
const rehearsal=computed(()=>data.value?.runs.find(r=>r.mode==='rehearsal'));
function fail(e:unknown){if(e instanceof RequestError&&e.status===401)emit('expired');error.value=e instanceof Error?e.message:'操作失败';}
async function load(){error.value='';try{data.value=await get('/api/v1/activities/'+props.activityId+'/configuration');data.value!.form.signupFieldIds??=[];data.value!.form.auxiliaryFieldIds=[];dirty.value=false;preview.value=false;confirmation.value='';}catch(e){fail(e);}}
watch(()=>props.activityId,load,{immediate:true});
watch(()=>props.revision,version=>{if(data.value&&BigInt(version)>BigInt(data.value.version))data.value.version=version;});
watch(()=>props.section,()=>{message.value='';error.value='';confirmation.value='';});
async function save(section:'form'|'rule'|'prizes'){
 if(!data.value||locked.value)return;
 if(section==='form'&&materialsSettings.value&&!materialsSettings.value.validate()){checkinTab.value='materials';await nextTick();materialsSettings.value.focusError();return;}
 if(section!=='form'){
  if(data.value.rule.mode==='max'&&(!Number.isInteger(data.value.rule.maxWins)||Number(data.value.rule.maxWins)<1)){error.value='请填写有效的整场最多中奖次数';return;}
  if(data.value.prizes.some(p=>!Number.isInteger(p.total)||p.total<1||!Number.isInteger(p.batch)||p.batch<1||p.batch>Math.min(p.total,10))){error.value='请填写有效奖项名额；每轮人数须为 1–10 人且不能超过总名额';return;}
 }
 saving.value=true;error.value='';message.value='';
 try{const path=section==='form'?'checkin':'prize-settings';
 const value=section==='form'?{form:data.value.form,h5BackgroundAssetId:props.backgroundId??null,showBackground:props.showBackground??true,materials:{buttonText:data.value.materials.buttonText.trim(),type:data.value.materials.type,link:data.value.materials.type==='link'?data.value.materials.link:'',images:data.value.materials.type==='images'?data.value.materials.images.map(({id,name})=>({id,name})):[]}}:{rule:data.value.rule,prizes:data.value.prizes,reservations:data.value.prizes.filter(p=>p.mode!=='random').map(p=>({prizeId:p.id,participantIds:data.value!.reservations.filter(r=>r.prize_id===p.id).map(r=>r.participant_id)}))};
 await write('/api/v1/activities/'+props.activityId+'/configuration/'+path,'PUT',{value,...(section!=='form'&&data.value.firstFormalStarted?{confirmed:true,reason:reason.value}:{})},{'If-Match':String(data.value.version)});await load();message.value='配置已保存';emit('changed');}
 catch(e){if(section==='form'&&e instanceof RequestError){if(e.code==='INVALID_MATERIALS'||(e.code==='ASSET_REJECTED'&&e.message.includes('资料')))checkinTab.value='materials';else if(e.code==='ASSET_REJECTED'||e.code==='INVALID_SETTINGS')checkinTab.value='background';else if(e.code==='INVALID_CONFIGURATION'||e.code==='INVALID_TEXT'||e.code==='INVALID_FIELDS')checkinTab.value='fields';}fail(e);}finally{saving.value=false;}
}
function addField(){data.value?.form.fields.push({id:crypto.randomUUID(),name:'',type:'text',hint:'',required:false,options:[]});dirty.value=true;}
function changeType(f:Field){f.options=f.type!=='single'?[]:[{id:crypto.randomUUID(),label:''}];dirty.value=true;}
function removeField(id:string){if(!data.value)return;const f=data.value.form;f.fields=f.fields.filter(x=>x.id!==id);if(f.titleFieldId===id)f.titleFieldId=null;f.auxiliaryFieldIds=[];f.signupFieldIds=f.signupFieldIds.filter(x=>x!==id);dirty.value=true;}
function move(index:number,offset:number){const fields=data.value!.form.fields;[fields[index],fields[index+offset]]=[fields[index+offset]!,fields[index]!];dirty.value=true;}
function addPrize(){data.value?.prizes.push({id:crypto.randomUUID(),name:'',total:1,batch:1,mode:'random',theme:'dream-planet'});dirty.value=true;}
function batch(p:Prize){p.batch=Math.min(p.total,10);}
function selectedPeople(prizeId:string){return data.value!.reservations.filter(r=>r.prize_id===prizeId).map(r=>r.participant_id);}
function choose(prizeId:string,id:string,checked:string|number|boolean){if(!data.value)return;data.value.reservations=data.value.reservations.filter(r=>!(r.prize_id===prizeId&&r.participant_id===id));if(checked)data.value.reservations.push({prize_id:prizeId,participant_id:id});}
async function searchPeople(prizeId:string){const q=(queries[prizeId]??'').trim();results[prizeId]=[];totals[prizeId]=0;if(!q||!data.value)return;searching[prizeId]=true;const activity=props.activityId;try{const res=await get<{items:Person[];total:number}>('/api/v1/activities/'+activity+'/participants?'+new URLSearchParams({mode:data.value.phase==='formal'?'formal':'rehearsal',search:q}));if(activity!==props.activityId||q!==(queries[prizeId]??'').trim())return;results[prizeId]=res.items;totals[prizeId]=res.total;for(const person of res.items)if(!data.value.participants.some(p=>p.id===person.id))data.value.participants.push(person);}catch(e){fail(e);}finally{searching[prizeId]=false;}}
function unchoose(prizeId:string,id:string){if(data.value)data.value.reservations=data.value.reservations.filter(r=>r.prize_id!==prizeId||r.participant_id!==id);}
function personName(id:string){return data.value?.participants.find(p=>p.id===id)?.nickname??'已选人员';}
const titleField=computed({get:()=>data.value?.form.titleFieldId??'',set:(value:string)=>{if(data.value)data.value.form.titleFieldId=value||null;}});
const formalEmpty=computed(()=>{const r=data.value?.runs.find(r=>r.mode==='formal');return !!r&&!r.participants&&!r.rounds&&!r.awards;});
async function generateParticipants(){
 if(!data.value||!rehearsal.value||locked.value)return;
 if(!Number.isInteger(simulationCount.value)||Number(simulationCount.value)<1||Number(simulationCount.value)>5000){error.value='请填写 1–5000 的整数';return;}
 saving.value=true;error.value='';message.value='';
 try{
  const result=await write<{added:number;simulated:number;participants:number}>('/api/v1/activities/'+props.activityId+'/rehearsal/simulated-participants','POST',{target:simulationCount.value,generation:rehearsal.value.generation},{'If-Match':String(data.value.version)});
  await load();message.value=result.added?'已新增 '+result.added+' 名模拟参与者，彩排名单共 '+result.participants+' 人':'模拟参与者已准备完成，头像已更新';emit('changed');
 }catch(e){fail(e);}finally{saving.value=false;}
}
async function mode(){if(!data.value||!rehearsal.value)return;saving.value=true;error.value='';try{await write('/api/v1/activities/'+props.activityId+'/mode/'+confirmation.value,'POST',{confirmation:confirmation.value,generation:rehearsal.value.generation},{'If-Match':String(data.value.version)});await load();message.value='操作已完成';emit('changed');}catch(e){fail(e);}finally{saving.value=false;}}
</script>
<template>
<section class="configuration">
<div v-if="section!=='form'" class="heading page-heading"><div><h2>{{section==='prizes'?'奖项设置':'模式切换'}}</h2><p>{{section==='prizes'?'设置中奖规则、奖项名额与颁发方式，统一保存后生效。':'查看彩排与正式数据，完成准备后启用正式活动。'}}</p></div></div>
<TopNotice v-if="error" :text="error" kind="error"></TopNotice><TopNotice v-if="message" :text="message" kind="success"></TopNotice>
<template v-if="data">
<p v-if="data.phase==='expired'">活动已到期，配置仅供查看。</p>
<div v-if="section==='form'" class="checkin-layout"><div class="checkin-controls">

<p v-if="data.firstFormalStarted">首次正式开奖后，字段结构已锁定。</p>
<ElForm @submit.prevent="save('form')" @input="dirty=true" @invalid.capture="revealInvalidField">
<ElTabs v-model="checkinTab" class="checkin-tabs"><ElTabPane label="签到页背景" name="background"><fieldset class="background-slot" :disabled="locked"><slot name="background" /></fieldset></ElTabPane><ElTabPane name="fields"><template #label>签到字段 <span class="field-count">{{data.form.fields.length}} / 3</span></template><fieldset class="field-settings" :disabled="locked||data.firstFormalStarted"><p class="field-intro">最多添加 3 个字段，每个名称最多 8 个字；修改即时同步到右侧预览。</p><div v-if="!data.form.fields.length" class="empty-note">还没有附加字段，参与者只需使用微信头像和昵称签到。</div>
<article v-for="(f,i) in data.form.fields" :key="f.id">
<div class="row tw:flex tw:items-center tw:gap-3 tw:flex-wrap"><strong>字段 {{i+1}}</strong><ElButton @click="move(i,-1)" :disabled="(locked||data.firstFormalStarted)||(i===0)" native-type="button">上移</ElButton><ElButton @click="move(i,1)" :disabled="(locked||data.firstFormalStarted)||(i===data.form.fields.length-1)" native-type="button">下移</ElButton><ElButton @click="removeField(f.id)" :disabled="(locked||data.firstFormalStarted)" native-type="button">删除字段</ElButton></div>
<div class="field-definition-row"><label>名称<ElInput aria-label="字段名称" v-model="f.name" maxlength="8" required :disabled="(locked||data.firstFormalStarted)" /><small>{{f.name.length}} / 8 字</small></label><label>类型<ElSelect v-model="f.type" @change="changeType(f)" :disabled="(locked||data.firstFormalStarted)" aria-label="类型"><ElOption value="text" :disabled="(locked||data.firstFormalStarted)" label="单行文本" /><ElOption value="number" label="数字（整数）" /><ElOption value="single" :disabled="(locked||data.firstFormalStarted)" label="下拉单选" /></ElSelect><small v-if="f.type==='number'">仅支持整数，含 0 和负数</small></label><div class="field-required"><span>必填</span><ElCheckbox v-model="f.required" aria-label="必填" :disabled="locked||data.firstFormalStarted" /></div></div>
<div v-if="f.options.length" class="field-options-grid"><div v-for="(o,j) in f.options" :key="o.id" class="field-option"><label>选项 {{j+1}}<ElInput v-model="o.label" maxlength="100" required :disabled="(locked||data.firstFormalStarted)" aria-label="选项" /></label><ElButton @click="f.options.splice(j,1)" :disabled="(locked||data.firstFormalStarted)||(f.options.length<=1)" native-type="button">删除选项</ElButton></div></div>
<ElButton v-if="f.type==='single'" :disabled="locked||data.firstFormalStarted||f.options.length>=50" native-type="button" @click="f.options.push({id:uuid(),label:''})">＋ 添加选项</ElButton>
</article>
<ElButton @click="addField" :disabled="locked||data.firstFormalStarted||data.form.fields.length>=3" native-type="button">＋ 添加字段</ElButton>
</fieldset></ElTabPane><ElTabPane label="展示信息" name="display"><fieldset class="field-settings display-settings" :disabled="locked||data.firstFormalStarted">
<div class="winner-display"><h3>中奖展示信息</h3><label>主标题<ElSelect v-model="titleField" :empty-values="[null,undefined]" :disabled="locked||data.firstFormalStarted" aria-label="主标题"><ElOption value="" :disabled="(locked||data.firstFormalStarted)" label="微信昵称" /><ElOption v-for="f in data.form.fields" :key="f.id" :value="f.id" :disabled="(locked||data.firstFormalStarted)" :label="f.name||'未命名字段'" /></ElSelect></label>
<p>只展示一个字段，未填写所选字段时使用微信昵称。</p></div>
<div class="winner-display signup-display"><h3>签到展示信息</h3><p>可选择多个字段，显示在手机签到成功页昵称下方；未填写的内容自动隐藏。</p>
<ElCheckbox v-for="f in data.form.fields" :key="f.id" :model-value="data.form.signupFieldIds.includes(f.id)" :disabled="locked||data.firstFormalStarted" @change="checked=>{data!.form.signupFieldIds=data!.form.signupFieldIds.filter(id=>id!==f.id);if(checked)data!.form.signupFieldIds.push(f.id);dirty=true}">{{f.name||'未命名字段'}}</ElCheckbox>
<p v-if="!data.form.fields.length">添加签到字段后可选择展示信息。</p><p>删除字段或更改类型后，已有签到资料仍保留原版本信息。</p></div>
</fieldset></ElTabPane><ElTabPane label="活动资料" name="materials"><ActivityMaterialsSettings ref="materialsSettings" :activity-id="activityId" :model-value="data.materials" :disabled="locked" @busy="materialsUploading=$event" @expired="emit('expired')" @preview="materialsPreview=$event;previewMaterialsOpen=false"/></ElTabPane></ElTabs><div class="save-bar tw:flex tw:items-center tw:justify-between tw:gap-3"><small>背景、签到字段、展示信息与活动资料一起保存</small><ElButton class="primary" :disabled="locked" native-type="submit" type="primary">{{saving?'保存中…':'保存'}}</ElButton></div></ElForm>
</div><div class="phone-dock"><div class="preview-caption">{{checkinTab==='materials'?(previewMaterialsOpen?'活动资料预览':'签到成功页预览'):'手机实时预览'}} <small>修改即时呈现，保存后生效</small></div>
<div class="phone"><div class="phone-screen" :class="{'signup-result-surface':checkinTab==='materials'}" :style="showBackground&&backgroundUrl?{backgroundImage:'linear-gradient(#11162c66,#11162cbb),url('+backgroundUrl+')'}:{}">
<div class="phone-status">9:41 <span>● ▰</span></div><div class="phone-bar">‹ <span>活动签到</span> ···</div>
<div class="phone-content" :class="{'no-fields':checkinTab!=='materials'&&!data.form.fields.length,'signup-result-layout':checkinTab==='materials'&&!previewMaterialsOpen}"><template v-if="checkinTab==='materials'"><MaterialsGallery v-if="previewMaterialsOpen&&materialsPreview?.type==='images'" :materials="materialsPreview" @back="previewMaterialsOpen=false"/><SignupSuccess v-else :person="{nickname:'微信昵称',avatarUrl:'/avatar-placeholder.svg',displayFields:data.form.fields.filter(f=>data!.form.signupFieldIds.includes(f.id)).map(f=>({id:f.id,label:f.name||'未命名字段',value:'示例内容'}))}" :materials="materialsPreview" @open="openMaterialsPreview"/></template><template v-else><div class="preview-profile"><img src="/avatar-placeholder.svg" alt="微信头像预览"><strong>微信昵称</strong></div><template v-if="data.form.fields.length"><SignupFields ref="previewFields" :fields="data.form.fields" preview/><ElButton class="phone-submit" native-type="button" @click="previewSignup">立即签到</ElButton></template>
</template></div><small class="phone-organizer">{{organizer||'欢迎参加本场活动'}}</small></div></div><small>按 375 × 667 内容区设计；小屏和放大字体时可滚动。</small></div></div>
<template v-else-if="section==='prizes'">
<ElForm @submit.prevent="data.firstFormalStarted?confirmation='rule':save('prizes')" @invalid.capture="revealInvalidField">
<ElTabs v-model="prizeTab" class="settings-tabs"><ElTabPane label="奖项列表" name="prizes"><fieldset class="prize-panel" :disabled="locked"><div class="section-title"><h3>奖项列表 <small>{{data.prizes.length}} 个奖项 · 共 {{data.prizes.reduce((sum,p)=>sum+(Number(p.total)||0),0)}} 个名额</small></h3></div><div v-if="!data.prizes.length" class="empty-note">尚未添加奖项。先创建奖项，再设置名额和每轮人数。</div>
<ElCard class="prize-card" v-for="(p,i) in data.prizes" :key="p.id" shadow="never" :body-style="{padding:'0'}"><div class="row tw:flex tw:items-center tw:gap-3 tw:flex-wrap"><h3>奖项 {{i+1}}</h3><ElButton @click="data.prizes.splice(i,1)" :disabled="(locked)||(data.lockedPrizeIds?.includes(p.id))" native-type="button">删除奖项</ElButton></div><p v-if="data.lockedPrizeIds?.includes(p.id)">本奖项已抽取，名称、总名额、颁发方式及删除操作已锁定；仍可调整每轮人数和未颁发的指定名单。彩排如需重设核心配置，可在模式切换中清空彩排数据后修改。</p><div class="grid prize-fields"><label>奖项名称<ElInput :disabled="(locked)||(data.lockedPrizeIds?.includes(p.id))" v-model="p.name" maxlength="100" required aria-label="奖项名称" /></label><label>总名额<ElInputNumber :disabled="(locked)||(data.lockedPrizeIds?.includes(p.id))" v-model="p.total" controls-position="right" :precision="0" step-strictly :min="1" required @change="batch(p)" aria-label="总名额" /></label><label>每轮人数<ElInputNumber v-model="p.batch" controls-position="right" :precision="0" step-strictly :min="1" :max="Math.min(p.total,10)" required :disabled="(locked)" aria-label="每轮人数" /></label><label>颁发方式<ElSelect :disabled="(locked)||(data.lockedPrizeIds?.includes(p.id))" v-model="p.mode" aria-label="颁发方式"><ElOption value="random" :disabled="(locked)" label="随机" /><ElOption value="designated" :disabled="(locked)" label="指定" /></ElSelect></label><label>抽奖主题<ElSelect v-model="p.theme" :aria-label="(p.name||'本奖项')+'抽奖主题'" :disabled="(locked)"><ElOption value="dream-planet" :disabled="(locked)" label="梦幻星球" /><ElOption value="starlight-matrix" :disabled="(locked)" label="星光矩阵" /><ElOption value="star-wave" :disabled="(locked)" label="星轨光波" /><ElOption value="starlight-corridor" :disabled="(locked)" label="星光长廊" /><ElOption value="galaxy-waterfall" :disabled="(locked)" label="星河瀑布" /></ElSelect></label></div><div v-if="p.mode!=='random'" class="designated"><p v-if="p.mode==='designated'">每轮优先颁发给已选且合资格的人员，其余名额随机抽取。未选择人员时全部随机；未轮到的指定人员保留到后续轮次。例如 3 个名额选择 1 人，其余 2 人随机；选择 3 人则全部指定。</p><h4>指定获奖人员 · 已选择 {{selectedPeople(p.id).length}} / {{p.total}}</h4><p>从当前{{data.phase==='formal'?'正式':'彩排'}}已签到名单选择。同名人员使用编号区分；指定名额会占用整场中奖次数。</p><div class="person-search"><ElInput v-model="queries[p.id]" :aria-label="p.name+'指定人员搜索'" maxlength="100" placeholder="输入微信昵称或人员编号" @input="results[p.id]=[];totals[p.id]=0" @keydown.enter.prevent="searchPeople(p.id)" :disabled="(locked)" /><ElButton @click="searchPeople(p.id)" :disabled="(locked)||(searching[p.id]||!queries[p.id]?.trim())" native-type="button">{{searching[p.id]?'查找中…':'查找人员'}}</ElButton></div><p>默认不展开名单。昵称重名时请核对完整编号；粘贴人员编号可更快定位。</p><div v-if="selectedPeople(p.id).length" class="selected-people"><strong>已选人员</strong><div v-for="id in selectedPeople(p.id)" :key="id">{{personName(id)}} · {{id}} <ElButton @click="unchoose(p.id,id)" :disabled="(locked)" native-type="button">移除</ElButton></div></div><p v-if="(totals[p.id]??0)>25">找到 {{totals[p.id]}} 人，仅展示前 25 人，请补充昵称或编号缩小范围。</p><p v-if="queries[p.id]?.trim()&&totals[p.id]===0&&!searching[p.id]">输入关键词后点击查找；无匹配时请核对昵称或编号。</p><div class="people-list"><ElCheckbox v-for="person in results[p.id]||[]" :key="person.id" :model-value="selectedPeople(p.id).includes(person.id)" :disabled="locked||!person.eligible||(!selectedPeople(p.id).includes(person.id)&&selectedPeople(p.id).length>=p.total)" @change="choose(p.id,person.id,$event)">{{person.nickname}} · {{person.id}}{{person.eligible?'':'（无资格）'}}</ElCheckbox></div></div></ElCard>
<p>总名额 1–10 人默认一轮；超过 10 人默认每轮 10 人。每轮可设 1–10 人，最后一轮按剩余名额抽取。</p><ElButton @click="addPrize" :disabled="locked||data.prizes.length>=200" native-type="button">＋ 添加奖项</ElButton>
</fieldset></ElTabPane><ElTabPane label="中奖规则" name="rules"><fieldset class="rule-panel" :disabled="locked"><label class="rule-label">每人整场中奖次数<ElSelect v-model="data.rule.mode" @change="data.rule.maxWins=data.rule.mode==='max'?2:null" :disabled="(locked)" aria-label="每人整场中奖次数"><ElOption value="once" :disabled="(locked)" label="整场最多一次（默认）" /><ElOption value="across" :disabled="(locked)" label="跨奖项可重复中奖" /><ElOption value="max" :disabled="(locked)" label="自定义整场最多次数" /></ElSelect></label><ElInputNumber v-if="data.rule.mode==='max'" v-model="data.rule.maxWins" controls-position="right" :precision="0" step-strictly :min="1" required :disabled="(locked)" /><p>同一奖项最多有效中奖一次；指定颁发也计入次数。</p></fieldset></ElTabPane></ElTabs><div class="save-bar tw:flex tw:items-center tw:justify-between tw:gap-3"><small>中奖规则、奖项及指定名单一起保存</small><ElButton class="primary" :disabled="locked" native-type="submit" type="primary">{{saving?'保存中…':'保存'}}</ElButton></div></ElForm>
</template>
<template v-else>
<div class="mode-banner"><div><small>当前活动状态</small><h3>{{data.phase==='formal'?'正式活动':data.phase==='expired'?'已到期':'彩排模式'}}</h3><p>新活动从空名单开始，可按需生成模拟参与者；模拟参与者仅用于彩排。</p></div><span class="mode-badge">{{data.phase==='formal'?'正式':data.phase==='expired'?'只读':'彩排'}}</span></div>
<ElTabs v-model="modeTab" class="settings-tabs mode-tabs"><ElTabPane label="清空彩排数据" name="cleanup"><section class="mode-cleanup"><h3>清空彩排数据</h3><p>清除全部彩排参与者（含模拟用户）和抽奖记录，清空后不自动补充。仅需重新试抽时，请到中奖名单中使用“清空抽奖”。</p><ul><li>清除彩排签到、中奖及抽奖进度</li><li>保留活动资料、背景、字段与奖项</li><li>保留结束日期与活动创建名额</li></ul><ElAlert class="status-note" type="info" :closable="false" show-icon><template #title>清空后无法恢复，需要二次确认。</template></ElAlert><div class="mode-cleanup-actions"><ElButton class="danger-outline" :disabled="locked||data.phase!=='rehearsal'" @click="confirmation='clear-rehearsal'" native-type="button" type="danger" plain>清空彩排数据</ElButton></div></section></ElTabPane><ElTabPane label="模拟参与者" name="simulation"><section class="mode-cleanup">
<h3>生成模拟参与者</h3><p>补足到指定的模拟参与者总数，用于彩排试抽。已有人员与中奖记录保留，正式名单不受影响。</p>
<p>当前模拟参与者 {{rehearsal?.simulated??0}} 人 · 彩排名单共 {{rehearsal?.participants??0}} 人</p>
<ElForm class="simulation-form" @submit.prevent="generateParticipants">
<label for="simulation-count">模拟参与者总数（1–5000）</label>
<ElInputNumber id="simulation-count" v-model="simulationCount" :min="1" :max="5000" :precision="0" :step="1" controls-position="right" :disabled="locked||data.phase!=='rehearsal'" aria-label="模拟参与者总数" />
<ElButton type="primary" native-type="submit" :loading="saving" :disabled="locked||data.phase!=='rehearsal'">生成模拟参与者</ElButton>
</ElForm><p>每位模拟参与者使用不同的测试头像。例如已有 100 人，填写 2000 只新增 1900 人；填写原人数可更新旧版头像，不会重复添加。减少人数需先清空彩排数据。</p>
</section></ElTabPane><ElTabPane label="启用正式活动" name="promote"><section class="mode-readiness"><h3>启用正式活动</h3><p>以下为接入检查及活动状态，启用正式活动前会再次确认。</p>
<ul class="conditions"><li>{{data.wechatVerified?'✓':'○'}} 微信接入已就绪</li><li>{{data.phase!=='expired'?'✓':'○'}} 活动尚未到期</li><li>{{data.runs.some(r=>r.drawing)?'○':'✓'}} 没有正在抽取的轮次</li><li>{{formalEmpty?'✓':'○'}} 正式名单及中奖数据为空</li></ul>
<ElAlert v-if="!data.wechatVerified" class="status-note" type="info" :closable="false" show-icon><template #title>微信接入尚未就绪，请在签到设置中完成域名设置并点击「检查微信接入」。</template></ElAlert><p>启用后正式名单从空开始，彩排历史保留为只读，不能切回。</p><ElButton class="primary" :disabled="locked||data.phase!=='rehearsal'||!data.wechatVerified||!formalEmpty" @click="confirmation='promote'" native-type="button" type="primary">启用正式活动</ElButton></section>
</ElTabPane></ElTabs>

</template>
<ElDialog :model-value="!!confirmation" title="确认操作" width="560px" append-to-body :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" @close="confirmation=''">
<h3>{{confirmation==='rule'?'确认修改中奖规则':confirmation==='promote'?'确认启用正式活动':confirmation==='reset-draw'?'确认仅重置彩排抽奖':'确认清空彩排数据'}}</h3>
<p>{{confirmation==='rule'?'已有中奖结果保持不变，新规则用于后续抽取。':confirmation==='promote'?'正式名单从空名单开始，彩排历史保留为只读。此操作无法撤回。':confirmation==='reset-draw'?'将清空彩排中奖、作废、补抽记录和轮次进度，无法撤销。签到名单、活动和奖项保留；恢复因不在场排除的人员，手动排除不变。保留未颁发指定名单，已颁发的指定人员需重新选择。请等待操作完成后再使用大屏。':'将删除彩排签到、中奖与试抽记录，无法撤销。活动资料、字段、奖项、结束时间和创建名额保持不变。'}}</p>
<ElForm @submit.prevent="confirmation==='rule'?save('rule'):mode()"><label v-if="confirmation==='rule'">修改原因<ElInput v-model="reason" required maxlength="300" aria-label="修改原因" /></label><ElButton type="primary" :disabled="saving" native-type="submit">确认操作</ElButton><ElButton @click="confirmation=''" :disabled="saving" native-type="button">取消</ElButton></ElForm>
</ElDialog>
</template>
</section>
</template>
